#!/usr/bin/env python3
"""Dataset browser: one section per training block with facts and random full-text samples rendered as conversations.
Usage: python3 cluster/dataset_samples_page.py results/block_samples.jsonl <out.html>"""
import json, sys, html, collections
IN, OUT = sys.argv[1], sys.argv[2]
samples = json.load(open(IN))
E = lambda t: html.escape(str(t)).replace('�', '&#xFFFD;')

# facts per block: (plan block, rows we take, licence, one-line description)
FACTS = {
 'Dolci · Precise IF (verified constraints)': ('verified constraint following', '137k, all', 'ODC-BY', 'Persona-grounded prompts with explicit, checker-verified constraints. The IFEval skill.'),
 'IFEval-like, filtered (Qwen2.5-72B, checker-verified)': ('verified constraint following', '56k, all', 'Qwen 2.5 licence', 'Prompts in the IFEval shape with Qwen2.5-72B answers; only rows where every checker passes.'),
 'Tulu 3 · persona instruction following': ('verified constraint following', 'inside Dolci Precise IF', 'ODC-BY', 'The 30k ancestor of Dolci Precise IF.'),
 'Dolci · Math, persona GSM and algebra': ('grade-school math', '60k', 'ODC-BY', 'Word problems written around personas, step-by-step solutions.'),
 'Dolci · Math, OpenMathInstruct-2 slice': ('grade-school math', 'inside the 60k', 'CC-BY-4.0', 'GSM8K-style problems with solutions.'),
 'OpenMathInstruct-2 (GSM8K-style)': ('grade-school math', '40k', 'CC-BY-4.0', 'Same source, sampled directly from the 22M-row release.'),
 'Nemotron IF-Chat v3 · chat split (GLM-5 answers)': ('general chat and advice', '100k', 'ODC-BY, CC-BY, Apache, other', 'Human prompts from LMArena, LMSYS and WildChat; GLM-5 answers picked best-of-N. June 2026. The main chat source.'),
 'Nemotron IF-Chat v3 · instruction-following split': ('verified constraint following, after our checker pass', 'up to 50k', 'as above', 'Constraint prompts on human seeds; answers by a judge, not by checkers.'),
 'Tulu 3 · WildChat (GPT-4 answers)': ('general chat and advice', '20k', 'ODC-BY', 'Real user prompts from WildChat with GPT-4 answers.'),
 'SmolTalk2 · Magpie Ultra': ('general chat and advice', '20k', 'Llama 3.1 licence', 'Prompts and answers generated by Llama-3.1-405B, filtered by quality.'),
 'SmolTalk2 · OpenHermes 2.5': ('general chat and advice', '10k', 'mixed', 'A 2023 aggregate of GPT-4 instruction data; the oldest source in the mix.'),
 'Dolci · Chat (OpenAssistant)': ('general chat and advice', 'about 7k, all', 'Apache-2.0', 'Human-written conversations from OpenAssistant. Dolci\'s only Chat rows; the WildChat-GPT-4.1 set named on its card is not in the release.'),
 'Dolci · Coding': ('coding', '100k', 'ODC-BY', 'Python algorithm tasks, Evol-CodeAlpaca, persona code.'),
 'SmolTalk2 · rewrite': ('rewriting, summarising, editing', 'in the 50k', 'Apache-2.0', 'Rewrite a given text in a given style.'),
 'SmolTalk2 · summarize': ('rewriting, summarising, editing', 'in the 50k', 'Apache-2.0', 'Summarise a given text.'),
 'SmolTalk2 · table tasks': ('rewriting, summarising, editing', 'in the 50k', 'MIT', 'Table-based questions and transformations.'),
 'Dolci · Reasoning (verifiable, traces removed)': ('reasoning and logic', 'in the 50k', 'ODC-BY', 'Verifiable reasoning problems; the answer without the long trace.'),
 'Dolci · Other, logic puzzles': ('reasoning and logic', 'in the 50k', 'ODC-BY', 'Zebra-style logic puzzles with a checkable answer.'),
 'Dolci · Tool Use': ('tool use', '30k', 'ODC-BY', 'Function-calling dialogues; the tool calls are shown as TOOL_CALLS.'),
 'Dolci · Science': ('science and knowledge QA', '15k', 'ODC-BY', 'Physics, chemistry, biology problems from OpenThoughts3, traces removed.'),
 'Dolci · Other, FLAN': ('science and knowledge QA, screened', '15k', 'ODC-BY', 'Old NLP task templates: QA, NLI, trivia, often American.'),
 'SmolTalk2 · multilingual, eight languages': ('other European languages', '25k', 'Apache-2.0', 'Chat in eight languages generated by Qwen3-32B.'),
 'EuroBlocks · French and German': ('other European languages', '25k', 'composite, Llama clause', 'EuroLLM\'s synthetic SFT rows; we already adapted slices of these in round one.'),
 'Dolci · Safety, WildGuardMix': ('safety, screened', 'in the 15k', 'Apache-2.0', 'Adversarial and benign prompts with refusals or compliance.'),
 'Dolci · Safety, CoCoNot': ('safety, screened', 'in the 15k', 'ODC-BY', 'Contextual non-compliance: requests that should be declined or clarified; we adapted a Greek slice of this in round one.'),
 'Dolci · Multilingual (Aya)': ('not in the mix', '0', 'Apache-2.0', 'Shown for reference: the Aya rows Dolci carries.'),
 'Ours · Greek, adapted (no_robots, everyday, skills…)': ('Greek', '20k, seen twice', 'mixed', 'Our round-one data: one random row from each of the eleven files. Most files are Greek conversations adapted to the Greek point of view; apertus_en, euroblocks_de and euroblocks_fr are the cross-language lane, where the user writes in English, German or French and the answer keeps a Greek vantage.'),
}
ORDER = ['verified constraint following','verified constraint following, after our checker pass','grade-school math','general chat and advice','coding','rewriting, summarising, editing','reasoning and logic','tool use','science and knowledge QA','science and knowledge QA, screened','other European languages','safety, screened','Greek','not in the mix']
by_block = collections.OrderedDict()
for s in samples: by_block.setdefault(s['block'], []).append(s)
blocks = sorted(by_block, key=lambda b: (ORDER.index(FACTS.get(b, ('zz',))[0]) if FACTS.get(b, ('zz',))[0] in ORDER else 99, b))

css = """
:root{--bg:#e9edf1;--paper:#fbfbfc;--ink:#151a20;--muted:#5b6672;--rule:#cfd6dd;--band:#dfe5eb;--accent:#245c8a;--user:#eef3f7;--asst:#fbfbfc;--tool:#f4efe3;
--serif:"Literata",Georgia,serif;--sans:"Source Sans 3",-apple-system,"Segoe UI",Helvetica,Arial,sans-serif;--mono:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--bg:#11161b;--paper:#1a2027;--ink:#e6e9ec;--muted:#9aa5b1;--rule:#33404c;--band:#222b34;--accent:#7fb3dc;--user:#1f2a33;--asst:#1a2027;--tool:#2a2620}}
:root[data-theme="dark"]{--bg:#11161b;--paper:#1a2027;--ink:#e6e9ec;--muted:#9aa5b1;--rule:#33404c;--band:#222b34;--accent:#7fb3dc;--user:#1f2a33;--asst:#1a2027;--tool:#2a2620}
*{box-sizing:border-box} body{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.5;margin:0}
main{max-width:1100px;margin:0 auto;padding:30px 24px 80px}
h1{font-family:var(--serif);font-size:30px;margin:0 0 6px} h2{font-family:var(--serif);font-size:21px;margin:34px 0 6px;border-bottom:1px solid var(--rule);padding-bottom:5px}
.eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:var(--accent);margin:0 0 6px}
p{max-width:80ch} .facts{display:flex;flex-wrap:wrap;gap:6px 20px;font-size:13px;color:var(--muted);margin:2px 0 10px}.facts b{color:var(--ink)}
nav{background:var(--paper);border:1px solid var(--rule);padding:12px 16px;margin:14px 0 24px;font-size:13px;columns:2;column-gap:28px}nav a{display:block;color:var(--accent);text-decoration:none;margin:2px 0}
details{background:var(--paper);border:1px solid var(--rule);margin:8px 0;padding:0 14px}summary{cursor:pointer;padding:9px 0;font-size:13.5px}summary .m{font-family:var(--mono);font-size:11.5px;color:var(--muted);margin-left:8px}
.turn{border-left:3px solid var(--rule);padding:8px 12px;margin:8px 0 10px;white-space:pre-wrap;font-size:13.5px;max-height:30em;overflow:auto}
.turn.user{background:var(--user);border-color:var(--accent)}.turn.assistant{background:var(--asst)}.turn.system,.turn.tool,.turn.developer{background:var(--tool);font-family:var(--mono);font-size:12.5px}
.role{font-family:var(--mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:3px}
.note{font-size:13px;color:var(--muted)}
"""
h = [f'<title>Round Two Data Samples</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Literata:opsz,wght@7..72,400;7..72,600&family=Source+Sans+3:wght@400;600&family=JetBrains+Mono:wght@400;500&display=swap"><style>{css}</style><main>']
h.append('<p class="eyebrow">Greek SFT round two · the training mix, row by row · sampled 2026-09-04</p><h1>Round Two Data Samples</h1>')
h.append(f'<p>Random rows from every block of the planned stage-one mix, full text, every turn shown in order. {len(samples)} rows across {len(blocks)} sources. Tool calls appear as TOOL_CALLS where the assistant turn carried a call instead of text. Each section states the plan block the source feeds, how many rows the plan takes from it, its licence, and what it is. These rows are unfiltered: identity lines, American framing and errors are shown as they are, because that is what the annotation pass has to catch.</p>')
h.append('<nav>' + ''.join(f'<a href="#b{i}">{E(b)} <span class="m">({len(by_block[b])})</span></a>' for i, b in enumerate(blocks)) + '</nav>')
for i, b in enumerate(blocks):
    f = FACTS.get(b, ('?', '?', '?', ''))
    h.append(f'<h2 id="b{i}">{E(b)}</h2><div class="facts"><span>plan block: <b>{E(f[0])}</b></span><span>rows taken: <b>{E(f[1])}</b></span><span>licence: <b>{E(f[2])}</b></span><span>source: <b>{E(by_block[b][0]["meta"].get("repo",""))}</b></span></div><p>{E(f[3])}</p>')
    for j, s in enumerate(by_block[b]):
        t = s['turns']; first = next((x['content'] for x in t if x['role'] == 'user'), t[0]['content'] if t else '')
        tag = ''
        if b.startswith('Ours') and s['meta'].get('files') and j < len(s['meta']['files']): tag = s['meta']['files'][j].replace('natural_greek_sft_', '').replace('.jsonl', '') + ' · '
        if s['meta'].get('langid'): tag = f"{s['meta']['langid']} · {s['meta'].get('task','')} · "
        h.append(f'<details{" open" if j == 0 else ""}><summary><span class="m" style="margin:0 6px 0 0">{E(tag)}</span>{E(first[:110].replace(chr(10)," "))}{"…" if len(first) > 110 else ""}<span class="m">{len(t)} turns</span></summary>')
        for x in t:
            r = x.get('role') or '?'; h.append(f'<div class="turn {E(r)}"><div class="role">{E(r)}</div>{E(x.get("content") or "")}</div>')
        h.append('</details>')
h.append('</main>')
open(OUT, 'w', encoding='utf-8').write('\n'.join(h)); print('wrote', OUT, round(len('\n'.join(h)) / 1e6, 2), 'MB', len(samples), 'rows', len(blocks), 'blocks')
